<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>License Manager</title><link rel="stylesheet" href="/assets/css/legacy-style.css"><link rel="stylesheet" href="/assets/css/app.css"></head><body><main class="card card-wide"><h1>License Manager</h1><?php foreach (($errors ?? []) as $error): ?><p class="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></p><?php endforeach; ?><p><a href="/license-activation">Activate New License</a></p><table class="table"><thead><tr><th>ID</th><th>Key</th><th>Domain</th><th>Status</th><th>Expiry</th><th>Last Verified</th></tr></thead><tbody><?php if (($rows ?? []) === []): ?><tr><td colspan="6">No licenses found.</td></tr><?php else: foreach ($rows as $r): ?><tr><td><?= (int) $r['license_id'] ?></td><td><?= htmlspecialchars($r['license_key'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($r['domain'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($r['status'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($r['expiry_date'], ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) ($r['last_verified_at'] ?? ''), ENT_QUOTES, 'UTF-8') ?></td></tr><?php endforeach; endif; ?></tbody></table><p><a href="/dashboard">Back to Dashboard</a></p></main></body></html>
